import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"九叹·怨思","description":"","frontmatter":{"title":"九叹·怨思","date":"2026-11-24T00:00:00.000Z","seq":50,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"离世","link":"/blogs/楚辞/离世.html"},"next":{"text":"远逝","link":"/blogs/楚辞/远逝.html"}},"headers":[],"relativePath":"blogs/楚辞/九叹·怨思.md","filePath":"blogs/楚辞/九叹·怨思.md"}'),o={name:"blogs/楚辞/九叹·怨思.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="九叹·怨思" tabindex="-1">九叹·怨思 <a class="header-anchor" href="#九叹·怨思" aria-label="Permalink to &quot;九叹·怨思&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">惟郁郁之忧毒兮，志坎壈而不违。</p><p class="poem-stanza">身憔悴而考旦兮，日黄昏而长悲。</p><p class="poem-stanza">闵空宇之孤子兮，哀枯杨之冤雏。</p><p class="poem-stanza">孤雌吟于高墉兮，鸣鸠栖于桑榆。</p><p class="poem-stanza">玄蝯失于潜林兮，独偏弃而远放。</p><p class="poem-stanza">征夫劳于周行兮，处妇愤而长望。</p><p class="poem-stanza">申诚信而罔违兮，情素洁于纽帛。</p><p class="poem-stanza">光明齐于日月兮，文采耀燿于玉石。</p><p class="poem-stanza">伤压次而不发兮，思沉抑而不扬。</p><p class="poem-stanza">芳懿懿而终败兮，名靡散而不彰。</p><p class="poem-stanza">背玉门以奔骛兮，蹇离尤而干诟。</p><p class="poem-stanza">若龙逢之沉首兮，王子比干之逢醢。</p><p class="poem-stanza">念社稷之几危兮，反为雠而见怨。</p><p class="poem-stanza">思国家之离沮兮，躬获愆而结难。</p><p class="poem-stanza">若青蝇之伪质兮，晋骊姬之反情。</p><p class="poem-stanza">恐登阶之逢殆兮，故退伏于末庭。</p><p class="poem-stanza">孽臣之号咷兮，本朝芜而不治。</p><p class="poem-stanza">犯颜色而触谏兮，反蒙辜而被疑。</p><p class="poem-stanza">菀蘼芜与菌若兮，渐藁本于洿渎。</p><p class="poem-stanza">淹芳芷于腐井兮，弃鸡骇于筐簏。</p><p class="poem-stanza">执棠谿以刜蓬兮，秉干将以割肉。</p><p class="poem-stanza">筐泽泻以豹鞟兮，破荆和以继筑。</p><p class="poem-stanza">时溷浊犹未清兮，世殽乱犹未察。</p><p class="poem-stanza">欲容与以俟时兮，惧年岁之既晏。</p><p class="poem-stanza">顾屈节以从流兮，心巩巩而不夷。</p><p class="poem-stanza">宁浮沅而驰骋兮，下江湘以邅回。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">山中槛槛余伤怀兮，征夫皇皇其孰依兮，</p><p class="poem-stanza">经营原野杳冥冥兮，乘骐骋骥舒吾情兮，</p><p class="poem-stanza">归骸旧邦莫谁语兮，长辞远逝乘湘去兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
